// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.20;

interface IReferralRegistry {
    function recordDeposit(address referrer, address referee, uint256 ethAmount, uint256 shares) external;
    function depositReferralFeeShares(uint256 shares) external;
}

// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.20;

/// @title IStakingModule - common interface implemented by every Router-managed module
/// @notice The Router only knows about modules through this interface. Each module is
///         responsible for its own ETH custody, validator orchestration (if any), and
///         oracle integration. The Router enforces global mint caps and routes deposits.
///
///         `receiveDeposit()` is invoked by the Router when a user submits ETH; the
///         module must accept the value and update its internal accounting.
///
///         `totalEth()` returns the module's contribution to `totalPooledEther`. For a
///         validator module that's `bufferedEther + beaconBalance`; for an LST wrap
///         module it's `priceOracle.getEthValue(lstHeld)`.
///
///         `moduleType()` is a tag used by tooling (kept opaque from the Router).
interface IStakingModule {
    /// @notice Called by the Router when a user deposits ETH. Module credits its buffer.
    function receiveDeposit() external payable;

    /// @notice Total ETH attributable to this module — buffered + beacon (or LST-equivalent).
    function totalEth() external view returns (uint256);

    /// @notice Static identifier (e.g. keccak256("SOLO_VALIDATOR")).
    function moduleType() external pure returns (bytes32);
}

// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.20;

/// @title IStakingRouter - module-facing surface of the Router
/// @notice Modules call back into the Router for two purposes:
///           1. Reporting beacon balance changes (validator modules).
///           2. Notifying that buffered ETH was just sent to the beacon deposit
///              contract — used by the Router to update its `moduleBeaconBalance`
///              baseline so subsequent oracle reports represent only rewards/losses.
///         For LST modules, `wrapFromModule` and `unwrapToModule` mint/burn shares
///         on entry/exit since LST flows do not use the standard `submit()` path.
interface IStakingRouter {
    struct ModuleInfo {
        address addr;
        bytes32 moduleType;
        uint256 mintCapEth;
        bool active;
        bool paused;
    }

    /// @notice Called by a validator module after the oracle's sanity-checked report.
    ///         Router computes the delta vs. its stored baseline and rebases stToken.
    function reportModuleBeaconBalance(bytes32 moduleId, uint256 newBeaconBalance) external;

    /// @notice Called by a validator module immediately after pushing ETH to the beacon
    ///         deposit contract. Updates the Router's beacon-balance baseline so the
    ///         next oracle report does not double-count the principal.
    function notifyBeaconDeposit(bytes32 moduleId, uint256 amount) external;

    /// @notice Called by an LST module to mint stToken shares on LST deposit.
    function wrapFromModule(bytes32 moduleId, address recipient, uint256 ethEquiv) external;

    /// @notice Called by an LST module to burn stToken shares on LST withdrawal.
    function unwrapToModule(bytes32 moduleId, address caller, uint256 stTokenAmount)
        external
        returns (uint256 ethValue);

    /// @notice Module registry getter.
    function modules(bytes32 moduleId)
        external
        view
        returns (address addr, bytes32 moduleType, uint256 mintCapEth, bool active, bool paused);
}

contracts/v2/modular-staking/ShareMath.s.content:
// SPDX-License-Identifier: BUSL-1.1
pragma solidity 0.8.20;

/// @title ShareMath - precision share accounting for the SharedStake V2 staking core
/// @notice All arithmetic uses 256-bit integers; Solidity 0.8 reverts on overflow.
///         Rounding policy: share minting rounds DOWN (protects pool);
///         pooled-ETH-by-shares rounds DOWN (protects pool on redemption).
library ShareMath {
    /// @dev Bootstrap: first depositor receives shares 1:1 with wei.
    ///      Prevents the classic "first deposit inflation" attack because the
    ///      attacker cannot make totalPooledEth >> totalShares before any shares exist.
    function getSharesByPooledEth(
        uint256 ethAmount,
        uint256 totalShares,
        uint256 totalPooledEth
    ) internal pure returns (uint256) {
        if (totalPooledEth == 0) {
            // Bootstrap: 1 wei => 1 share
            return ethAmount;
        }
        // Rounds DOWN: minter receives floor(shares). Pool balance never overstated.
        return (ethAmount * totalShares) / totalPooledEth;
    }

    function getPooledEthByShares(
        uint256 sharesAmount,
        uint256 totalShares,
        uint256 totalPooledEth
    ) internal pure returns (uint256) {
        if (totalShares == 0) {
            return 0;
        }
        // Rounds DOWN: redeemer receives floor(eth). Pool never drained beyond entitlement.
        return (sharesAmount * totalPooledEth) / totalShares;
    }

    /// @notice Exchange rate: how many wei one share is worth.
    ///         Returns 0 when no shares exist (undefined until first deposit).
    function sharePrice(uint256 totalShares, uint256 totalPooledEth) internal pure returns (uint256) {
        if (totalShares == 0) return 0;
        return (totalPooledEth * 1e18) / totalShares;
    }
}

